-- Import av 15 års historik (2012-2026) från Run_As_You_Are__Resultat.xlsx
--
-- Lägg till en unik-constraint på runners.name så vi kan upsert:a säkert
-- (annars riskerar ett omkört av denna migration att skapa dubbletter,
-- och den befintliga testraden för "Daniel Solving" från röktestet
-- slås ihop med den riktiga importraden istället för att bli en dubblett).
alter table runners add constraint runners_name_key unique (name);

-- Upplagor 2012-2026 (2027 finns redan - skapad under röktestet).
on conflict (year) do nothing;

-- Löpare: namn + antal gånger de var värd (stjärnorna i originalarket).
on conflict (name) do update set host_count = excluded.host_count;

-- Resultat per löpare och år.
-- NI/DNR/DNC: bara status, ingen placering (appens egna scoring-motor
--   räknar själv ut "sist plus 2/4" från samma års faktiska antal löpare).
-- Allt annat (inklusive 2015 där vi saknade tidtagning, och Andreas
--   DNF 2021): riktig placering, ingen tid.
on conflict (edition_id, runner_id) do nothing;
